code.workForce.calculatePayrollBurnrate():
function calculatePayrollBurnrate() constant onlyOwner returns (uint)
 {
 uint monthlyPayout;
 for( uint x = 0; x < workcrew.length; x++ )
 {
 monthlyPayout += workcrew[x].yearlySalaryUSD / 12;
 }
 return monthlyPayout;
 }

